"use strict";

import { BaseRepository } from "approot/global/repository.js";
import { FilterPanelInfo, FilterSource, FilterContext } from "approot/global/components/filterpanel/filterpanel.model";

export enum ReportOutputType {
	EmailDelivery = "EmailDelivery",
	Excel = "Excel",
	Pdf = "Pdf",
	Html = "Html"
}

export interface GenerateReportOptions {
	output?: ReportOutputType;
}

export interface ReportGroup {
	id: string;
	title: string;
	reports: Report[];
}

export interface Report {
	id: string;
	title: string;
	path: string;
}

export interface ReportDetailedInfo {
	id: string;
	name: string;
	group: string;
	level: any;
	order: number;
	filterPanel: FilterPanelInfo,
	presentTypes: ReportOutputType[]
}

export interface PreparedReport {
	report : ReportDetailedInfo;
	filterSources: FilterSource[]
}

export class ReportsRepository extends BaseRepository {

	getReportInitFiltersUrl(reportId: string): string {
		return `/webapi/reports/${reportId}/initfilters`;
	}

	getReportList(): Promise<ReportGroup[]> {
		return this.$http.get("/webapi/reports")
			.then(this.handleResponse)
			.catch(this.handleError);
	}

	getReport(id: string) : Promise<PreparedReport> {
		return this.$http.get(`/webapi/reports/${id}`)
			.then(this.handleResponse)
			.catch(this.handleError);
	}

	getFavorites() : Promise<string[]> {
		return this.$http.get(`/webapi/reports/favorites`)
			.then(this.handleResponse)
			.catch(this.handleError);
	}

	addFavorites(id: string) : Promise<void> {
		return this.$http.put(`/webapi/reports/favorites/${id}`)
			.then(this.handleResponse)
			.catch(this.handleError);
	}

	removeFavorites(id: string) : Promise<void>{
		return this.$http.delete(`/webapi/reports/favorites/${id}`)
			.then(this.handleResponse)
			.catch(this.handleError);
	}

	getReportTask(reportId: string, ctx: FilterContext, options: GenerateReportOptions): Promise<number> {
		return this.$http.post(`/webapi/reports/${reportId}/queue`, ctx, { params: options })
			.then(
				this.handleResponse,
				(response) => {
					if (response.data && response.data.isInformation) {
						this.$dialogs.message(response.data.message);
					} else {
						this.handleError(response);
					}
				}
			);
	}

	getReportResult(fileId: string): Promise<any> {
		return this.$http.get(`/webapi/files/${fileId}`)
			.then(this.handleResponse)
			.catch(this.handleError);

	}
}


