"use strict";

import * as Rights from "approot/global/references/rights.js";
import * as Roles from "approot/global/references/roles.js";
import { AppLoader } from "approot/global/apploader";
import { DownloadService } from "approot/global/common.module";
import { PageContext, AppContext } from "approot/global/services/context";
import { ReportsRepository, GenerateReportOptions, ReportOutputType, PreparedReport } from "../reports.repository";
import { DialogsService } from "approot/global/providers/uikit.dialogs";
import { TaskQueueService } from "approot/global/services/queue/taskqueue.service";
import { QueueExecutionOptions } from "approot/global/services/queue/taskqueue.model";
import { FilterPanelSettings, IFilterPanel, FilterContext } from "approot/global/components/filterpanel/filterpanel.model";

interface JQueryPrintUtils<TElement extends Element = HTMLElement> extends JQuery<TElement> {
	printUtils()
}

interface JQueryPrintUtilsStatic extends JQueryStatic {
	<TElement extends Element = HTMLElement>(selector: string): JQueryPrintUtils<TElement>;
}

declare var $: JQueryPrintUtilsStatic;

export class ReportCtrl {

	public state = {
		generated: false
	}

	public filterPanel: IFilterPanel;
	public filterPanelSettings: FilterPanelSettings;

	public options = {
		emailDelivery: false
	}

	public reportId : string;
	public isFavorite: boolean;
	private reportInfo : PreparedReport;
	public reportHtml: string;
	public emptyChoice: boolean = false;

	private popupWindow: any;

	/*@ngInject*/
	constructor(
		pageContext: PageContext,
		private language,
		private appContext: AppContext,
		private reportsRepository: ReportsRepository,
		private $dialogs: DialogsService,
		private taskQueueService: TaskQueueService,
		private downloadService: DownloadService,
		protected $appLoader: AppLoader,
		private $routeParams: any) {

		this.state = {
			generated: false
		};
		this.filterPanel = null;
		this.options = {
			emailDelivery: false
		};

		this.reportId = this.getReportId();

		this.init(pageContext);
	}

	public init(pageContext: PageContext) {
		pageContext.parent = {
			title: this.language.Generic.MenuFolders.kFNReports,
			href: `/`
		};

		this.reportsRepository.getFavorites().then((favList) => {
			this.isFavorite = favList && favList.indexOf(this.reportId) > -1;
		});

		this.reportsRepository
			.getReport(this.reportId)
			.then((reportInfo) => {
				this.reportInfo = reportInfo;
				this.options.emailDelivery = reportInfo.report.presentTypes.indexOf(ReportOutputType.EmailDelivery) != -1;

				pageContext.title = reportInfo.report.name;

				const reportFpUrl = this.reportsRepository.getReportInitFiltersUrl(this.reportId);
				const fpModel = reportInfo.report.filterPanel;
				const fpSources = reportInfo.filterSources;

				this.filterPanelSettings = {
					sources: fpSources,
					info: fpModel,
					url: reportFpUrl,
					styles: {
						compact: false
					},
					initUrl: reportFpUrl,
					events: {
						ready: () => this.onReady(),
						emptyChoice: () => {
							this.emptyChoice = true;
							this.$appLoader.hide();
						}
					}
				}
			});
	}

	public getReportId() {
		return this.$routeParams.reportId;
	}

	public getReportTitle() {
		return this.reportInfo.report.name;
	}

	public onReady() {
		this.emptyChoice = false;
		this.$appLoader.hide();
	}

	public generate(options: GenerateReportOptions, extraParams?) {
		this.reportId = this.getReportId();

		if (!this.filterPanel.validate()) {
			return;
		}

		options = options || {};
		extraParams = extraParams || [];

		var reportParams = [
			{ name: "SCHOOLYEARID", value: this.appContext.yearId },
			{ name: "SERVERTIMEZONE", value: this.appContext.serverTimeZone },
			{ name: "FULLSCHOOLNAME", value: this.appContext.fullSchoolName },
			{ name: "DATEFORMAT", value: this.appContext.dateFormat }
		];

		reportParams = reportParams.concat(extraParams);

		const ctx : FilterContext = {
			selectedData: this.filterPanel.getCtxValues(),
			params: reportParams
		};

		const loadFileAndDisplay = (fileId) => this.reportsRepository.getReportResult(fileId)
			.then((reportHtml: string) => {
				if (reportHtml.length > 1024 * 1024) {
					$(reportHtml).printUtils().toExcel();
				}
				else {
					this.state.generated = true;
					this.reportHtml = reportHtml;
				}
			});

		const downloadFile = (fileId: string) => {
			this.downloadService.downloadFile(`/webapi/files/${fileId}`);
		};

		let execOptions: QueueExecutionOptions = {
			getTaskFunc: () => this.reportsRepository.getReportTask(this.reportId, ctx, options),
			hint: this.language.Generic.Common.kProcessingInfoLetter
		}

		this.taskQueueService.execute<string>(execOptions)
			.then((reportResult) => {

				if (options.output === ReportOutputType.Pdf || options.output === ReportOutputType.Excel) {
					var fileId = reportResult;
					downloadFile(fileId);
					return;
				}
				else if (options.output === ReportOutputType.EmailDelivery) {
					var message = reportResult || "Отчет успешно отправлен получателям";
					this.$dialogs.message(message);
					return;
				}

				var fileId = reportResult;
				loadFileAndDisplay(fileId);
			});
	}

	generatePdf() {
		this.generate({ output: ReportOutputType.Pdf });
	}

	generateExcel() {
		this.generate({ output: ReportOutputType.Excel });
	}

	emailDelivery() {
		this.$dialogs.confirm("Получать подтверждения о прочтении сообщений?")
			.then(
				() => {
					this.generate({ output: ReportOutputType.EmailDelivery }, [{ name: "neednotify", value: 1 }]);
				},
				() => {
					this.generate({ output: ReportOutputType.EmailDelivery });
				}
			);
	}

	print() {
		$("#report").printUtils().toPrint().then((window) => {
			window.onload = () => {
				window.print();
				window.close();
			}
		});
	}

	export() {
		$("#report").printUtils().toExcel();
	}

	popup() {
		$("#report").printUtils().toPrint().then((window) => this.popupWindow = window);
	}

	canSend() {
		const isStaff = !this.appContext.hasRole(Roles.student) && !this.appContext.hasRole(Roles.parent);

		return isStaff && this.appContext.hasAnyRight([Rights.arMessagesSendReceive]);
	}

	send() {
		let reportName = this.getReportTitle() + " (" + this.language.Generic.Reports.kOn + " " + this.appContext.now + ")";
		$("#report").printUtils().send({ NA: reportName });
	}

	removeFromFavorites() {
		this.reportsRepository.removeFavorites(this.reportId).then(() => {
			this.isFavorite = false;
		});
	}

	addToFavorites() {
		this.reportsRepository.addFavorites(this.reportId).then(() => {
			this.isFavorite = true;
		});
	}
}

export const ReportComponent = {
	controller: ReportCtrl,
	controllerAs: "ctrl",
	templateUrl: "/static/dist/app/school/reports/report/report.component.html"
}


