"use strict";

import { AppLoader } from "approot/global/apploader";
import { ReportsRepository, ReportGroup, Report } from "../reports.repository";
import { PageContext } from "approot/global/services/context";
import { postTo } from "webroot/static/src/common/js/common.navigation";

export abstract class ReportListController{
	public reportGroups: ReportGroup[] = [];

	/*@ngInject*/
	constructor(
		pageContext: PageContext,
		private $location: ng.ILocationService,
		$appLoader: AppLoader,
		public language: any,
		reportsRepository: ReportsRepository) {

		pageContext.title = language.Generic.MenuFolders.kFNReports;
		pageContext.parent = null;

		reportsRepository.getReportList()
			.then((reportGroups) => {
				this.reportGroups = reportGroups;
				$appLoader.hide();
			});
	}

	abstract openLegacyReport(report: Report);

	viewReport(report: Report) {
		if (report.path.endsWith("Report.asp")) {
			this.$location.path(`${report.id.toLowerCase()}`);
		} else {
			this.openLegacyReport(report);
		}
	}
}

export class SchoolReportListController extends ReportListController {
	openLegacyReport(report: Report) {
		postTo({
			path: report.path,
			params: {
				RPNAME: report.title,
				RPTID: report.id
			}
		});
	}
}

export const ReportListComponent = {
	controller: SchoolReportListController,
	controllerAs: "ctrl",
	templateUrl: "/static/dist/app/school/reports/list/reportlist.component.html"
}


