declare var angular: ng.IAngularStatic;

const module = angular.module("irtech.netcity.em.reports",
	[
		"ngRoute", "ngSanitize", "ngMessages", "ui.select", "uikit.alerts", "uikit.dialogs", "ui.bootstrap",
		"irtech.netcity.common", "ngFileUpload", "ui.tree", "irtech.netcity.ui-components"
	]);

import { ReportsRepository, Report } from "approot/school/reports/reports.repository";
import { ReportListComponent, ReportListController } from "approot/school/reports//list/reportlist.component";
import { ReportComponent } from "approot/school/reports/report/report.component";
import { postTo } from "webroot/static/src/common/js/common.navigation";

export class EmReportListController extends ReportListController {
	openLegacyReport(report: Report) {
		let path = report.path;
		if (!path.startsWith("/")) {
			path = `/asp/EDUC_MANAGER/Reports/${path}`;
		}

		postTo({
			path: path,
			params: {
				RPNAME: report.title,
				RPTID: report.id
			}
		});
	}
}

const EMReportListComponent = {
	controller: EmReportListController,
	controllerAs: ReportListComponent.controllerAs,
	templateUrl: ReportListComponent.templateUrl
}

/*@ngInject*/
const config = ($routeProvider, $locationProvider: ng.ILocationProvider) => {
	$routeProvider
		.when("/list/", {
			templateUrl: EMReportListComponent.templateUrl,
			controller: EMReportListComponent.controller,
			controllerAs: EMReportListComponent.controllerAs
		})
		.when("/:reportId", {
			templateUrl: ReportComponent.templateUrl,
			controller: ReportComponent.controller,
			controllerAs: ReportComponent.controllerAs
		})
		.otherwise({
			templateUrl: EMReportListComponent.templateUrl,
			controller: EMReportListComponent.controller,
			controllerAs: EMReportListComponent.controllerAs
		});

	$locationProvider.hashPrefix("");
	$locationProvider.html5Mode({
		enabled: true,
		requireBase: true
	});
}

module
	.service("reportsRepository", ReportsRepository)
	.config(config);



